extern const EncEffectsPair _020FC40A[35];

u32 BattleStartGetTransition(u32 effectPairID, const FieldBattleDTO *dto);

u32 BattleStartGetTransition(u32 effectPairID, const FieldBattleDTO *dto) {
    GF_ASSERT(effectPairID < (enum EncEffectsPairID)45);

    // If the cut-in effect specifies, determine what effect to use
    // based on the encounter locale.
    if (_020FC40A[effectPairID].cutInEffect == ENCEFF_CUTIN_USE_LOCAL) {
        return ov01_021F0D20(dto);
    }

    return _020FC40A[effectPairID].cutInEffect;
}

u32 BattleStartGetMusic(u32 effectPairID, const FieldBattleDTO *dto);

u32 BattleStartGetMusic(u32 effectPairID, const FieldBattleDTO *dto) {
    GF_ASSERT(effectPairID < (enum EncEffectsPairID)45);

    return _020FC40A[effectPairID].sdatBGMusic;
}
